describe('Accessibility Error Messages', () => {
    beforeEach(() => {
        cy.visit('/your-page-url'); // Replace with the actual page URL
    });

    it('should announce error messages to screen readers', () => {
        cy.get('input[name="username"]').type('invalidUser');
        cy.get('input[name="password"]').type('wrongPassword');
        cy.get('button[type="submit"]').click();

        cy.get('.error-message') // Replace with the actual selector for error messages
            .should('be.visible')
            .invoke('attr', 'aria-live')
            .should('equal', 'assertive');

        cy.get('.error-message')
            .should('contain', 'Invalid username or password'); // Replace with actual error message
    });

    it('should not announce error messages when there are no errors', () => {
        cy.get('input[name="username"]').type('validUser');
        cy.get('input[name="password"]').type('correctPassword');
        cy.get('button[type="submit"]').click();

        cy.get('.error-message') // Replace with the actual selector for error messages
            .should('not.exist');
    });
});
